actions.action:
ob_zadal: f.ob_zadal, ob_zadal_meno: f.ob_zadal_meno,
ob_stav: f.ob_stav, ob_stav_label: f.ob_stav_label, ob_ceka_na: f.ob_ceka_na,
ob_predmet: f.ob_predmet, ob_suma: f.ob_suma;

def u = loggedUser()

change ob_zadal value { [u.id] }
change ob_zadal_meno value { kto(u) }
change ob_stav value { "koncept" }
change ob_stav_label value { "koncept" }
// Rozpisana objednavka lezi u toho, kto ju zacal. Notifikacia sa neposiela -
// nikto nema dostat mail o tom, ze si prave zalozil vlastnu ziadost.
change ob_ceka_na value { kto(u) }
changeCaseProperty("color").about { farba("koncept") }
changeCaseProperty("title").about { nazov(ob_predmet, ob_suma, "koncept") }

document.function:
{ ->
    // Hranica dvoch urovni schvalenia, v EUR s DPH: do limitu vratane staci
    // stredisko, nad limit schvaluje aj riaditel.
    //
    // Cita sa z konfiguracneho casu (`admin/nastavenia/sc_nastavenia`), aby sa dala
    // zmenit v appke a nie novou verziou siete. Ked konfiguracia neexistuje
    // alebo je prazdna, plati zabudovanych 1000 - appka musi fungovat aj
    // v instancii, kde konfiguracnu siet nikto nenaimportoval.
    def cfg = najnovsiCase("admin/nastavenia/sc_nastavenia")
    def v = cfg?.dataSet?.get("sc_limit")?.value
    if (v == null) return 1000.0d
    double d = (v as Number).doubleValue()
    return d > 0 ? d : 1000.0d
}

{ def u ->
    // Nie `u?.fullName` - `?.` chrani pred null, nie pred chybajucou property,
    // a na chybajucej vyhodi MissingPropertyException uprostred akcie.
    return (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
}

{ def ob_predmet, def ob_suma, def stavKod ->
    // BEZ STAVU - dovod je v `fa_faktura` pri tej istej funkcii: `Case.title`
    // je `String` a prelozit sa neda, kym pole `ob_stav_label` je
    // `enumeration_map`, teda prelozene, a je v zobrazeniach ako stlpec.
    def p = ((ob_predmet.value ?: "") as String).trim()
    if (p.length() > 60) p = p.substring(0, 57) + "..."
    def co = p ?: ((useCase.visualId ?: "?") as String)
    // Nula znamena "este nic nepridane" - `number` pole prazdne nevracia null,
    // takze bez tejto podmienky sa kazda nova objednavka vola "... 0.00 €".
    def suma = ob_suma.value
    if (suma != null && (suma as Number).doubleValue() > 0) {
        co = co + " · " + suma_slovom(ob_suma)
    }
    return co
}

{ def ob_historia, def text ->
    def ts = java.time.LocalDateTime.now()
            .format(java.time.format.DateTimeFormatter.ofPattern("d.M.yyyy HH:mm"))
    def log = (ob_historia.value ?: "") as String
    def riadok = ts + "  " + (text as String)
    change ob_historia value { log ? log + "\n" + riadok : riadok }
}

{ def ob_suma ->
    def v = ob_suma.value
    if (v == null) return false
    return (v as Number).doubleValue() > limit_riaditela()
}

{ def ob_suma, def ob_kontrola ->
    def v = ob_suma.value
    if (v == null) {
        change ob_kontrola value { "" }
        return false
    }
    def d = (v as Number).doubleValue()
    if (d <= 0) {
        change ob_kontrola value { "The estimated price must be greater than zero - the order cannot be submitted like this." }
        return true
    }
    if (d > limit_riaditela()) {
        change ob_kontrola value {
            "Nad " + String.format(java.util.Locale.US, "%.0f", limit_riaditela()) +
                    " EUR the director approves after the cost centre."
        }
        return true
    }
    change ob_kontrola value { "" }
    return false
}

{ def ob_polozky_json ->
    def raw = ((ob_polozky_json.value ?: "") as String).trim()
    if (!raw) return []
    try {
        return new groovy.json.JsonSlurper().parseText(raw) as List
    } catch (Exception e) {
        // Rozsypany JSON nesmie zhodit celu akciu - prazdny zoznam je horsi
        // vysledok, ale opravitelny.
        return []
    }
}

{ def polozky ->
    double sum = 0.0d
    polozky.each { pol ->
        double mn = ((pol.mnozstvo ?: 0) as Number).doubleValue()
        double cn = ((pol.cena ?: 0) as Number).doubleValue()
        sum += mn * cn
    }
    // Zaokruhlenie na centy: 0.1 + 0.2 v doublach nie je 0.3 a v sucte
    // desiatok riadkov to je vidno.
    return Math.round(sum * 100.0d) / 100.0d
}

{ def ob_polozky_json, def ob_polozky, def ob_polozky_vyber, def ob_suma, def ob_kontrola ->
    // Jedno miesto, ktore drzi vykreslenie, moznosti na odobranie a sucet
    // v zhode s JSONom. Kazdy, kto zoznam meni, konci volanim tejto funkcie.
    def list = polozky_zo_json(ob_polozky_json)
    def fmt = { def n -> String.format(java.util.Locale.US, "%.2f", (n as Number).doubleValue()) }
    def riadok = { def pol ->
        double mn = ((pol.mnozstvo ?: 0) as Number).doubleValue()
        double cn = ((pol.cena ?: 0) as Number).doubleValue()
        return (pol.nazov as String) + "  ·  " + fmt(mn) + " " + ((pol.jednotka ?: "ks") as String) +
                " × " + fmt(cn) + " € = " + fmt(mn * cn) + " €"
    }
    change ob_polozky value {
        list ? list.withIndex(1).collect { pol, i -> i + ". " + riadok(pol) }.join("\n")
             : ""
    }
    // Kluc moznosti nesmie obsahovat `.` ani `$` (Mongo to v nazvoch poli
    // zakazuje), preto id typu "p3" a nie nazov polozky.
    change ob_polozky_vyber options {
        list.collectEntries { pol -> [((pol.id ?: "?") as String): riadok(pol)] }
    }
    change ob_polozky_vyber value { [] }
    change ob_suma value { sucet_polozok(list) as Double }
    // Upozornenie na limit sa musi prepocitat tu: `ob_suma` uz nikto netypuje,
    // takze jeho `set` udalost sa cez formular nespusti.
    boolean varuj = prepocet(ob_suma, ob_kontrola)
    make ob_kontrola, visible on transitions when { varuj }
    make ob_kontrola, hidden  on transitions when { !varuj }
}

{ def ob_stredisko, def ob_zadal, def ob_schvalovatelia, def ob_historia ->
    // To iste ako v `fa_faktura`: kto smie schvalit TUTO objednavku. Retaz
    // (stredisko -> vsetci schvalovatelia -> riaditel) je zamerna a kazdy jej
    // stupen sa zapise do priebehu, aby objednavka v stredisku bez schvalovatela
    // necakala navzdy a bez vysvetlenia.
    def kod = ((ob_stredisko.value ?: "") as String).trim()
    def zadal = (userIdsOf(ob_zadal.value) ?: []).collect { it as String }
    def bezZadavatela = { List ids -> (ids ?: []).collect { it as String } - zadal }

    def kandidati = bezZadavatela(usersWithRoleAll("schv_" + kod))
    def preco = null
    if (!kandidati) {
        kandidati = bezZadavatela(usersWithRoleAll("schvalovatel"))
        preco = "the cost centre has no approver of its own, it goes to all approvers"
    }
    if (!kandidati) {
        kandidati = bezZadavatela(usersWithRoleAll("riaditel"))
        preco = "nobody but the director can approve this order"
    }
    change ob_schvalovatelia value { kandidati }
    if (preco) {
        zapis_historie(ob_historia, "smerovanie: " + preco)
    }
    return kandidati
}

{ def kod, def ob_zadal, def ob_schvalovatelia ->
    // Kto je na rade. ID, nie rola ako slovo - do `ob_ceka_na` patria mena.
    def k = ((kod ?: "") as String)
    if (k == "na_schvalenie") return userIdsOf(ob_schvalovatelia.value)
    if (k == "u_riaditela") return usersWithRoleAll("riaditel")
    // Objednat a potvrdit objednanie ma ten, kto o objednavku poziadal.
    if (k in ["na_objednanie", "vratena", "koncept"]) return userIdsOf(ob_zadal.value)
    return []
}

{ def kod, def ob_ceka_na, def ob_zadal, def ob_schvalovatelia, def ob_historia,
  def ob_predmet, def ob_suma, def ob_stredisko ->
    // Jedno miesto pre "u koho to lezi" a pre upozornenie toho, kto je na rade.
    // Rovnaky vzor ako v fa_faktura - keby to bolo rozpisane po prechodoch,
    // jeden z nich to vzdy zabudne.
    def k = ((kod ?: "") as String)
    def ids = cakajuci(k, ob_zadal, ob_schvalovatelia)
    def mena = menaUzivatelov(ids)
    change ob_ceka_na value { mena ? mena.join(", ") : "—" }

    def komu = ids ?: ((k in ["objednana", "zamietnuta"]) ? userIdsOf(ob_zadal.value) : [])
    if (!komu) return 0

    def popis = (((ob_predmet.value ?: "") as String).trim() ?: "objednávka")
    def telo = new StringBuilder()
    telo.append(veta_o_stave(k)).append("\n\n")
    telo.append("Order: ").append(popis).append("\n")
    telo.append("Cena:       ").append(suma_slovom(ob_suma)).append("\n")
    telo.append("Stredisko:  ").append(((ob_stredisko.value ?: "-") as String)).append("\n")
    telo.append("\neTask portal -> Orders and invoices -> Orders.\n")

    def poslane = notifikuj(komu, popis + " – " + veta_o_stave(k), telo.toString())
    if (poslane > 0) {
        zapis_historie(ob_historia, "upozornenie e-mailom: " + poslane + "×")
    }
    return poslane
}

{ def ob_zadal, def rola ->
    // STVORI OCI. `userIdsOf` je primitiv delegata - id z userList pola sa
    // nikdy netahaju rucne, `u?._id` zhodi celu akciu.
    def zadal = (userIdsOf(ob_zadal.value) ?: []).collect { it as String }
    def ja = loggedUser().id as String
    if (zadal.contains(ja)) {
        throw new java.lang.IllegalStateException(
                "You cannot approve an order you requested yourself as " + (rola as String) +
                        ". Let somebody else approve it.")
    }
}

actions.action:
ob_p_nazov: f.ob_p_nazov, ob_p_mnozstvo: f.ob_p_mnozstvo,
ob_p_jednotka: f.ob_p_jednotka, ob_p_cena: f.ob_p_cena,
ob_polozky_json: f.ob_polozky_json, ob_polozky: f.ob_polozky,
ob_polozky_vyber: f.ob_polozky_vyber, ob_polozky_sprava: f.ob_polozky_sprava,
ob_suma: f.ob_suma, ob_kontrola: f.ob_kontrola;

// Button nie je `finish`, takze vynimka by tu nemala komu nic povedat -
// chyba ide do `ob_polozky_sprava` a formular zostane otvoreny.
def nazov = ((ob_p_nazov.value ?: "") as String).trim()
def mn = (ob_p_mnozstvo.value == null) ? 1.0d : (ob_p_mnozstvo.value as Number).doubleValue()
def cn = (ob_p_cena.value == null) ? 0.0d : (ob_p_cena.value as Number).doubleValue()

if (!nazov) {
    change ob_polozky_sprava value { "Write what should be ordered." }
} else if (mn <= 0) {
    change ob_polozky_sprava value { "The quantity must be greater than zero." }
} else if (cn < 0) {
    change ob_polozky_sprava value { "The price cannot be negative." }
} else {
    def list = polozky_zo_json(ob_polozky_json)
    // Id je pocitadlo, nie index: po odobrani riadku by sa indexy precislovali
    // a zaskrtnutie v `ob_polozky_vyber` by ukazovalo na inu polozku.
    int next = 1
    list.each { pol ->
        // Zamerne bez regexu: `pflint` v `/p(\d+)/` vidi volanie metody `p(...)`
        // a hlasi preklep. Substring je aj tak citatelnejsi.
        def id = ((pol.id ?: "") as String)
        if (id.startsWith("p") && id.length() > 1 && id.substring(1).isInteger()) {
            int n = id.substring(1) as int
            if (n >= next) next = n + 1
        }
    }
    list.add([id       : "p" + next,
              nazov    : nazov,
              mnozstvo : mn,
              jednotka : (((ob_p_jednotka.value ?: "") as String).trim() ?: "ks"),
              cena     : cn])
    change ob_polozky_json value { groovy.json.JsonOutput.toJson(list) }
    render_polozky(ob_polozky_json, ob_polozky, ob_polozky_vyber, ob_suma, ob_kontrola)
    change ob_polozky_sprava value { "Added: " + nazov + " (" + list.size() + " v zozname)" }
    change ob_p_nazov value { "" }
    change ob_p_mnozstvo value { null }
    change ob_p_jednotka value { "" }
    change ob_p_cena value { null }
}

ob_polozky_json: f.ob_polozky_json, ob_polozky: f.ob_polozky,
ob_polozky_vyber: f.ob_polozky_vyber, ob_polozky_sprava: f.ob_polozky_sprava,
ob_suma: f.ob_suma, ob_kontrola: f.ob_kontrola;

def vybrane = ((ob_polozky_vyber.value ?: []) as List).collect { it as String } as Set
if (!vybrane) {
    change ob_polozky_sprava value { "Nothing is ticked." }
} else {
    def list = polozky_zo_json(ob_polozky_json)
    def zostava = list.findAll { pol -> !(((pol.id ?: "") as String) in vybrane) }
    change ob_polozky_json value { groovy.json.JsonOutput.toJson(zostava) }
    render_polozky(ob_polozky_json, ob_polozky, ob_polozky_vyber, ob_suma, ob_kontrola)
    change ob_polozky_sprava value { "Removed: " + (list.size() - zostava.size()) }
}

ob_suma: f.ob_suma, ob_kontrola: f.ob_kontrola;
boolean varuj = prepocet(ob_suma, ob_kontrola)
make ob_kontrola, visible on transitions when { varuj }
make ob_kontrola, hidden  on transitions when { !varuj }

ob_suma: f.ob_suma, ob_polozky_json: f.ob_polozky_json,
ob_polozky: f.ob_polozky, ob_polozky_vyber: f.ob_polozky_vyber,
ob_kontrola: f.ob_kontrola;

// Jedine miesto, ktore podanie naozaj zastavi. `required` overi len to, ze pole
// nie je prazdne, a poziadavky ziadne `required` nepokryje - su to riadky
// v JSONe, nie pole na formulari. Odmietnutie vracia HTTP 200 a dovod v tele
// ako `error`.
def polozky = polozky_zo_json(ob_polozky_json)
if (!polozky) {
    throw new java.lang.IllegalStateException(
            "Add at least one line - without it there is nothing to order.")
}

// Sucet sa prepocita TU a nie len v buttone: kto posle data cez API, formular
// (a s nim aj button) obchadza, a suma by zostala z predoslej verzie zoznamu.
// Nad limit ide objednavka riaditelovi, takze na tomto cisle zavisi smerovanie.
render_polozky(ob_polozky_json, ob_polozky, ob_polozky_vyber, ob_suma, ob_kontrola)

def v = ob_suma.value
if (v == null || (v as Number).doubleValue() <= 0) {
    throw new java.lang.IllegalStateException(
            "The line prices are zero. The approval limit stands on money, " +
                    "so even an estimate is better than nothing.")
}

ob_stav: f.ob_stav, ob_stav_label: f.ob_stav_label, ob_ziadane_o: f.ob_ziadane_o,
ob_kontrola: f.ob_kontrola, ob_historia: f.ob_historia,
ob_predmet: f.ob_predmet, ob_suma: f.ob_suma, ob_polozky_json: f.ob_polozky_json,
ob_stredisko: f.ob_stredisko, ob_zadal: f.ob_zadal, ob_ceka_na: f.ob_ceka_na,
ob_schvalovatelia: f.ob_schvalovatelia;

def opakovane = (((ob_stav.value ?: "") as String) == "vratena")
int pocet = polozky_zo_json(ob_polozky_json).size()

// Kto smie tuto objednavku schvalit. Prepocitava sa pri KAZDOM podani -
// po vrateni sa stredisko moze zmenit a s nim aj schvalovatel.
schvalovatelia_strediska(ob_stredisko, ob_zadal, ob_schvalovatelia, ob_historia)

change ob_stav value { "na_schvalenie" }
change ob_stav_label value { "na_schvalenie" }
changeCaseProperty("color").about { farba("na_schvalenie") }
change ob_ziadane_o value { java.time.LocalDateTime.now() }
change ob_kontrola value { "" }
zapis_historie(ob_historia, (opakovane ? "completed and resubmitted: " : "requested: ") +
        pocet + (pocet == 1 ? " line" : " lines") +
        " for " + suma_slovom(ob_suma) +
        (nad_limit(ob_suma) ? " (above the limit, it will go to the director too)" : ""))
changeCaseProperty("title").about { nazov(ob_predmet, ob_suma, "na_schvalenie") }
po_zmene_stavu("na_schvalenie", ob_ceka_na, ob_zadal, ob_schvalovatelia, ob_historia,
        ob_predmet, ob_suma, ob_stredisko)

ob_rozhodnutie: f.ob_rozhodnutie, ob_poznamka: f.ob_poznamka, ob_suma: f.ob_suma,
ob_zadal: f.ob_zadal,
ob_to_riaditel: f.ob_to_riaditel, ob_to_objednanie: f.ob_to_objednanie,
ob_to_koncept: f.ob_to_koncept, ob_to_uzavreta: f.ob_to_uzavreta;

// STVORI OCI. Je to tu a nie v udalosti `assign`, hoci tam by to zabralo
// skor: vynimka z akcie v `assign` vracia HOLE HTTP 500 bez spravy, kym tu
// vrati engine HTTP 200 a vetu v tele ako `error` (ENGINE_ISSUES E18).
nie_vlastnu(ob_zadal, "cost centre approver")

// SMEROVANIE MUSI BYT V phase="pre" (C4) - v `post` by sa token pohol
// s povodnymi nulami a case by ostal bez tokenu.
def volba = ((ob_rozhodnutie.value ?: "") as String).trim()

if (!volba) {
    throw new java.lang.IllegalStateException(
            "Choose whether you approve the order, return it for completion or reject it.")
}
if (!(volba in ["schvalit", "vratit", "zamietnut"])) {
    throw new java.lang.IllegalStateException("Unknown decision: " + volba)
}
if (volba != "schvalit" && !((ob_poznamka.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException(
            "Write the reason - otherwise the clerk does not know what to do with the order.")
}

boolean naRiaditela = (volba == "schvalit" && nad_limit(ob_suma))

change ob_to_riaditel   value { (naRiaditela ? 1 : 0) as Double }
change ob_to_objednanie value { ((volba == "schvalit" && !naRiaditela) ? 1 : 0) as Double }
change ob_to_koncept    value { (volba == "vratit" ? 1 : 0) as Double }
change ob_to_uzavreta   value { (volba == "zamietnut" ? 1 : 0) as Double }

ob_rozhodnutie: f.ob_rozhodnutie, ob_stav: f.ob_stav, ob_stav_label: f.ob_stav_label,
ob_poznamka: f.ob_poznamka, ob_historia: f.ob_historia, ob_suma: f.ob_suma,
ob_predmet: f.ob_predmet,
ob_ceka_na: f.ob_ceka_na, ob_zadal: f.ob_zadal,
ob_schvalovatelia: f.ob_schvalovatelia, ob_stredisko: f.ob_stredisko,
ob_schvalil_stredisko: f.ob_schvalil_stredisko, ob_schvalene_o: f.ob_schvalene_o;

def volba = ((ob_rozhodnutie.value ?: "") as String).trim()
def meno = kto(loggedUser())
def pozn = ((ob_poznamka.value ?: "") as String).trim()

def kod
if (volba == "vratit") {
    kod = "vratena"
    zapis_historie(ob_historia, "returned for completion (" + meno + "): " + pozn)
} else if (volba == "zamietnut") {
    kod = "zamietnuta"
    zapis_historie(ob_historia, "rejected by the cost centre (" + meno + "): " + pozn)
} else {
    change ob_schvalil_stredisko value { meno }
    if (nad_limit(ob_suma)) {
        kod = "u_riaditela"
        zapis_historie(ob_historia, "approved by the cost centre (" + meno + "), cena " +
                suma_slovom(ob_suma) + " is above the limit - going to the director" +
                (pozn ? ": " + pozn : ""))
    } else {
        kod = "na_objednanie"
        change ob_schvalene_o value { java.time.LocalDateTime.now() }
        zapis_historie(ob_historia, "approved by the cost centre (" + meno + ")" +
                (pozn ? ": " + pozn : ""))
    }
}

change ob_stav value { kod }
change ob_stav_label value { kod }
changeCaseProperty("color").about { farba(kod) }
// Vynulovat vyber, inak by pri dalsom kole bola v selecte predvyplnena minula
// volba a DOKONCIT by preslo bez toho, aby sa schvalovatel na cokolvek pozrel.
change ob_rozhodnutie value { null }
changeCaseProperty("title").about { nazov(ob_predmet, ob_suma, kod) }
po_zmene_stavu(kod, ob_ceka_na, ob_zadal, ob_schvalovatelia, ob_historia,
        ob_predmet, ob_suma, ob_stredisko)

ob_rozhodnutie: f.ob_rozhodnutie, ob_poznamka: f.ob_poznamka, ob_zadal: f.ob_zadal,
ob_to_riaditel: f.ob_to_riaditel, ob_to_objednanie: f.ob_to_objednanie,
ob_to_koncept: f.ob_to_koncept, ob_to_uzavreta: f.ob_to_uzavreta;

nie_vlastnu(ob_zadal, "director")

def volba = ((ob_rozhodnutie.value ?: "") as String).trim()
if (!volba) {
    throw new java.lang.IllegalStateException(
            "Choose whether you approve the order, return it for completion or reject it.")
}
if (!(volba in ["schvalit", "vratit", "zamietnut"])) {
    throw new java.lang.IllegalStateException("Unknown decision: " + volba)
}
if (volba != "schvalit" && !((ob_poznamka.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException(
            "Write the reason - otherwise the clerk does not know what to do with the order.")
}

// Vsetky styri flagy sa nastavuju vzdy: zdielaju ich arcy z troch prechodov
// a hodnota, ktoru tu niekto nechal, by smerovala aj to dalsie.
change ob_to_riaditel   value { 0 as Double }
change ob_to_objednanie value { (volba == "schvalit" ? 1 : 0) as Double }
change ob_to_koncept    value { (volba == "vratit" ? 1 : 0) as Double }
change ob_to_uzavreta   value { (volba == "zamietnut" ? 1 : 0) as Double }

ob_rozhodnutie: f.ob_rozhodnutie, ob_stav: f.ob_stav, ob_stav_label: f.ob_stav_label,
ob_poznamka: f.ob_poznamka, ob_historia: f.ob_historia, ob_suma: f.ob_suma,
ob_predmet: f.ob_predmet,
ob_ceka_na: f.ob_ceka_na, ob_zadal: f.ob_zadal,
ob_schvalovatelia: f.ob_schvalovatelia, ob_stredisko: f.ob_stredisko,
ob_schvalil_riaditel: f.ob_schvalil_riaditel, ob_schvalene_o: f.ob_schvalene_o;

def volba = ((ob_rozhodnutie.value ?: "") as String).trim()
def meno = kto(loggedUser())
def pozn = ((ob_poznamka.value ?: "") as String).trim()

def kod
if (volba == "vratit") {
    kod = "vratena"
    zapis_historie(ob_historia, "director returned it for completion (" + meno + "): " + pozn)
} else if (volba == "zamietnut") {
    kod = "zamietnuta"
    zapis_historie(ob_historia, "rejected by the director (" + meno + "): " + pozn)
} else {
    kod = "na_objednanie"
    change ob_schvalil_riaditel value { meno }
    change ob_schvalene_o value { java.time.LocalDateTime.now() }
    zapis_historie(ob_historia, "approved by the director (" + meno + ")" +
            (pozn ? ": " + pozn : ""))
}

change ob_stav value { kod }
change ob_stav_label value { kod }
changeCaseProperty("color").about { farba(kod) }
change ob_rozhodnutie value { null }
changeCaseProperty("title").about { nazov(ob_predmet, ob_suma, kod) }
po_zmene_stavu(kod, ob_ceka_na, ob_zadal, ob_schvalovatelia, ob_historia,
        ob_predmet, ob_suma, ob_stredisko)

ob_cislo: f.ob_cislo, ob_dodavatel: f.ob_dodavatel,
ob_to_riaditel: f.ob_to_riaditel, ob_to_objednanie: f.ob_to_objednanie,
ob_to_koncept: f.ob_to_koncept, ob_to_uzavreta: f.ob_to_uzavreta;

// Cislo objednavky je jedina stopa, po ktorej sa k nej da priradit faktura
// (`fa_objednavka`). Bez neho je objednavka uzavreta a nespojitelna.
if (!((ob_cislo.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException(
            "Fill in the order number the supplier was given.")
}
if (!((ob_dodavatel.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException("Fill in who you ordered from.")
}

change ob_to_riaditel   value { 0 as Double }
change ob_to_objednanie value { 0 as Double }
change ob_to_koncept    value { 0 as Double }
change ob_to_uzavreta   value { 1 as Double }

ob_stav: f.ob_stav, ob_stav_label: f.ob_stav_label, ob_historia: f.ob_historia,
ob_cislo: f.ob_cislo, ob_dodavatel: f.ob_dodavatel,
ob_objednal: f.ob_objednal, ob_objednane_o: f.ob_objednane_o,
ob_ceka_na: f.ob_ceka_na, ob_zadal: f.ob_zadal,
ob_schvalovatelia: f.ob_schvalovatelia, ob_stredisko: f.ob_stredisko,
ob_predmet: f.ob_predmet, ob_suma: f.ob_suma;

def meno = kto(loggedUser())

change ob_stav value { "objednana" }
change ob_stav_label value { "objednana" }
changeCaseProperty("color").about { farba("objednana") }
change ob_objednal value { meno }
change ob_objednane_o value { java.time.LocalDateTime.now() }
zapis_historie(ob_historia, "ordered (" + meno + ") u " +
        ((ob_dodavatel.value ?: "") as String).trim() + ", objednávka č. " +
        ((ob_cislo.value ?: "") as String).trim())
changeCaseProperty("title").about { nazov(ob_predmet, ob_suma, "objednana") }
po_zmene_stavu("objednana", ob_ceka_na, ob_zadal, ob_schvalovatelia, ob_historia,
        ob_predmet, ob_suma, ob_stredisko)
